  ('hakuba-japan', '08A', 'Hakuba', 'Japan', 'Ten resorts, one Olympic mountain, and the deep light', 'live', 'verified', 'northernLights', 'Japanese Alps/Nagano', '{"adventure","culinary","culture","expedition","family","hiking","romance","ski","ultra","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'core', '{"key_facts":["Hakuba Valley = ten linked resorts (Happo-One, Hakuba47, Goryu, Iwatake, Tsugaike, Cortina, Norikura, Sanosaka, Kashimayari, Jigatake) on one pass + free shuttle","Happo-One flagship (1998 Olympic alpine venue): base 760 m to summit 1,831 m, vertical 1,071 m, 52 km pistes (16 easy/26 int/10 diff), 21 lifts incl 1 gondola, longest run 8,000 m","Sea-of-Japan powder: ~11 m annual snowfall at Happo, Tsugaike ~12 m, Cortina the heaviest of the ten","Season early Dec-early May, powder heart Jan-Feb; Hakuba Valley all-mountain pass from ~JPY 10,400/day (2025-26; verify)","Night skiing: ABLE Hakuba Goryu (largest night area); Cortina select Jan-Feb dates; Happo none 2025-26 (verify per season)","Hakuba Happo Onsen: rare pH>11 alkaline water (marketed as Japan''s only natural hydrogen hot spring), four public bathhouses","Luxury tier: Courtyard by Marriott Hakuba (private onsen) + Phoenix Hotel & Chalets (Phoenix One 4-BR ultra chalet); deep chalet/villa rental market","Formal backcountry gate + mandatory registration system (gates at Happo/Goryu/Tsugaike/Norikura/Cortina); ~3-4 hr from Tokyo via Nagano Shinkansen + bus"],"safety":{"emergency":"110 police / 119 fire + ambulance / #7119 medical advice (verify Nagano); Nagano Multilingual Call Centre 0120-691-792; ambulance dispatch free","hospital":"Hakuba International Clinic (0261-85-2264, English, orthopedics, resort-partnered private ambulance); Omachi General (~40 min), Azumi (~1 hr), Matsumoto (~90 min) for major trauma via 119","malaria":"none","yellow_fever":"not required","activity_note":"SERIOUS AVALANCHE COUNTRY: JAN issues a DEDICATED daily Hakuba avalanche bulletin (data.nadare.jp/avalanche_areas/hakuba) - check every morning; backcountry only via designated gates with filed registration + beacon/probe/shovel + guide (BC prohibited at Jigatake/Kashimayari/Sanosaka/Hakuba47/Iwatake); tree-well/deep-snow immersion suffocation risk (never ski trees alone); cold/whiteout on exposed alpine gates","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/japan","read":"2026-08-31T18:23:04Z","page_updated":"2026-08-28T16:22:35+01:00","source_country":"japan","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"Deep winter (Christmas/NY + Jan-Feb powder heart + Lunar New Year + Australian January); chalet/hotel multiples + min-stay","shoulder":"Late Nov-mid Dec (early season) + Mar-early May (spring, firmer snow, longer days)","green":"May-Nov green season (festivals, Iwatake MTB park, hiking/rafting/ballooning; lowest rates)","booking_lead":"Christmas/NY + Jan + top chalets/branded hotels 6-12 mo; regular winter 3-6 mo; shoulder 1-3 mo (qualitative; verify)","off_season_specials":"Green-season festivals + MTB/hiking (Jun-Sep); spring-powder value (late Mar-Apr); long-stay winter chalets","event_peaks":"Christmas/NY, Japanese New Year (Shogatsu), Lunar New Year, Australian school holidays (all January), Golden Week spring tail","fire_date":"Next winter + luxury chalets/branded beds by prior spring/summer (6-12 mo); spring powder from Jan; green-season Hakuba from late winter"},"jewels":[{"name":"Ski ten resorts on one Hakuba Valley pass","status":"live","tier":"comfort","price_band":"~JPY 10,400/day; multi-day cheaper/day (approx)","timing":"ski ~early Dec-early May; powder heart Dec-Feb","draw_rank":1,"hook":"the valley links Jigatake, Kashimayari, Sanosaka, ABLE Hakuba Goryu, Hakuba47, Happo-One, Iwatake, Tsugaike","si":"ski","blurb":"the valley links Jigatake, Kashimayari, Sanosaka, ABLE Hakuba Goryu, Hakuba4